#!/usr/bin/env python3
"""Generate and validate result/INDEX.md.

The index is the entry point to the committed sweeps: one row per
(profile, measured tensor4all-rs revision), each linking to that sweep's report.
It is generated so that it cannot drift from the tree it describes.
"""

import argparse
import re
import sys
from pathlib import Path

RESULT = Path(__file__).resolve().parents[1] / "result"
HEADER = (
    "Generated by `scripts/gen_index.py`. **Do not edit by hand**; CI checks "
    "that this file is what the generator produces."
)


def pinned_revision() -> str:
    cargo = (RESULT.parent / "Cargo.toml").read_text()
    found = re.search(
        r'package = "tensor4all-itensorlike".*?rev = "([0-9a-f]+)"', cargo, re.S
    )
    if found is None:
        raise SystemExit("cannot read the tensor4all-rs pin from Cargo.toml")
    return found.group(1)


def metadata(path: Path) -> dict[str, str]:
    result = {}
    for line in path.read_text().splitlines():
        if ":" in line:
            key, value = line.split(":", 1)
            result[key.strip()] = value.strip()
    return result


def pages() -> list[dict[str, object]]:
    rows = []
    for run in sorted(RESULT.glob("*/*/run.yaml")):
        revision_dir = run.parent
        profile = revision_dir.parent.name
        meta = metadata(run)
        revision = meta.get("tensor4all_rs_rev", "")
        if not revision.startswith(revision_dir.name):
            raise SystemExit(
                f"{run}: directory name {revision_dir.name!r} does not match "
                f"tensor4all_rs_rev {revision!r}"
            )
        records = len(list((revision_dir / "raw").glob("*.json")))
        if records == 0:
            raise SystemExit(f"{revision_dir}: no JSON records")
        if not (revision_dir / "report.md").exists():
            raise SystemExit(f"{revision_dir}: no report.md")
        rows.append(
            {
                "profile": profile,
                "revision": revision,
                "date": meta.get("date_utc", ""),
                "threads": meta.get("threads", ""),
                "cpus": meta.get("cpu_affinity", ""),
                "chip": meta.get("chip", ""),
                "records": records,
                "path": revision_dir.relative_to(RESULT).as_posix(),
            }
        )
    rows.sort(key=lambda row: (row["date"], row["profile"]), reverse=True)
    return rows


def render(rows: list[dict[str, object]], pin: str) -> str:
    lines = [
        "# Result index",
        "",
        HEADER,
        "",
        f"- Pinned tensor4all-rs revision: `{pin}`",
        f"- Recorded sweeps: {len(rows)}",
        "",
        "One row is one complete sweep of the three maintained cases on one machine",
        "at one tensor4all-rs revision. `status` compares the measured revision with",
        "the pin in `Cargo.toml`: `current` is measured at it, `superseded` is not.",
        "A `-<n>t` profile is that machine's optional multithreaded scaling sweep,",
        "read against its one-thread profile rather than instead of it.",
        "",
        "| profile | tensor4all-rs | status | date (UTC) | threads | CPUs | records | report |",
        "| --- | --- | --- | --- | ---: | --- | ---: | --- |",
    ]
    for row in rows:
        status = "current" if row["revision"] == pin else "superseded"
        lines.append(
            f"| `{row['profile']}` | `{row['revision'][:12]}` | {status} | "
            f"{row['date']} | {row['threads']} | {row['cpus']} | {row['records']} | "
            f"[report.md]({row['path']}/report.md) |"
        )
    lines.append("")
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--check",
        action="store_true",
        help="fail instead of writing when result/INDEX.md is out of date",
    )
    args = parser.parse_args()

    text = render(pages(), pinned_revision())
    index = RESULT / "INDEX.md"
    if args.check:
        current = index.read_text() if index.exists() else ""
        if current != text:
            print(
                "result/INDEX.md is out of date; run scripts/gen_index.py",
                file=sys.stderr,
            )
            raise SystemExit(1)
        print("result/INDEX.md is current")
        return
    index.write_text(text)
    print(f"wrote {index}")


if __name__ == "__main__":
    main()
